import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnInit,
  OnDestroy,
  ViewChild,
  ElementRef,
} from '@angular/core';
/* STEP 9: KeyboardManager 適用 */
import { KeyboardManagerService } from '../../../../shared/services/keyboard-manager.service';
import { Subscription } from 'rxjs';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, FormArray, Validators } from '@angular/forms';
import { Title } from '@angular/platform-browser';
import { MatIconModule } from '@angular/material/icon';
import { MatChipsModule } from '@angular/material/chips';
import { COMMA, ENTER } from '@angular/cdk/keycodes';
import { MatChipInputEvent } from '@angular/material/chips';
import { SettingsTabNavComponent } from '../../components/settings-tab-nav/settings-tab-nav.component';
import { NotificationService } from '../../../../shared/services/notification.service';
/* 修正 No.53 (2026-04-24): ネイティブ confirm をサイト配色のモーダルへ置換 */
import { ConfirmDialogService } from '../../../../shared/services/confirm-dialog.service';

/** 経歴エントリの型 */
interface CareerEntry {
  periodFrom: string;
  periodTo: string;
  company: string;
  position: string;
  description: string;
}

/** 学歴エントリの型 */
interface EducationEntry {
  periodFrom: string;
  periodTo: string;
  school: string;
  major: string;
}

@Component({
  selector: 'app-profile-page',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    MatIconModule,
    MatChipsModule,
    SettingsTabNavComponent,
  ],
  templateUrl: './profile-page.component.html',
  styleUrls: ['./profile-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ProfilePageComponent implements OnInit, OnDestroy {
  /* STEP 9: KeyboardManager で SP キーボード時のページ高さ補正 */
  keyboardHeight = 0;
  private keyboardSub?: Subscription;
  profileForm!: FormGroup;
  avatarPreview: string | null = null;
  skills: string[] = [];
  readonly separatorKeyCodes = [ENTER, COMMA] as const;

  /* 修正 No.32/35/36/37 (2026-04-25): localStorage 永続化キー + プレビュー用スケール */
  private static readonly STORAGE_KEY = 'schecon.profile.v1';
  /** プレビューで表示する画像の倍率 (保存前のサイズ調整用スライダー) */
  avatarScale = 1;

  // アバターエディタ
  showAvatarEditor = false;
  avatarEditorSrc: string | null = null;
  avatarZoom = 1;
  avatarPanX = 0;
  avatarPanY = 0;
  private isDragging = false;
  private dragStartX = 0;
  private dragStartY = 0;
  private panStartX = 0;
  private panStartY = 0;

  @ViewChild('avatarCanvas') avatarCanvas!: ElementRef<HTMLCanvasElement>;

  constructor(
    private fb: FormBuilder,
    private titleService: Title,
    private cdr: ChangeDetectorRef,
    private notification: NotificationService,
    /* 修正 No.53 (2026-04-24) */
    private confirmDialog: ConfirmDialogService,
    /* STEP 9: KeyboardManager */
    private keyboard: KeyboardManagerService,
  ) {}

  ngOnInit(): void {
    this.titleService.setTitle('マイページ・プロフィール | 日程調整ツール"スケコン"');
    this.initForm();
    /* 修正 No.32/37 (2026-04-25): 既存アカウントのプロフィール情報を localStorage から復元 */
    this.loadProfileFromStorage();
    /* STEP 9: キーボード高さ購読 */
    this.keyboardSub = this.keyboard.keyboardHeight$.subscribe(h => {
      this.keyboardHeight = h;
      this.cdr.markForCheck();
    });
  }

  ngOnDestroy(): void {
    this.keyboardSub?.unsubscribe();
  }

  /* 修正 No.32/37 (2026-04-25): localStorage からプロフィール情報を読み込む */
  private loadProfileFromStorage(): void {
    try {
      const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(ProfilePageComponent.STORAGE_KEY) : null;
      if (!raw) return;
      const data = JSON.parse(raw);
      if (!data || typeof data !== 'object') return;

      // プリミティブ項目を FormControl に反映
      const primitiveKeys = [
        'lastName','firstName','furigana','company','department','jobTitle',
        'catchphrase','bio','birthplace','birthday','phone','address','website',
        'facebook','twitter','instagram',
      ];
      const patch: Record<string, any> = {};
      primitiveKeys.forEach(k => { if (data[k] != null) patch[k] = data[k]; });
      this.profileForm.patchValue(patch);

      // careers / educations (FormArray)
      if (Array.isArray(data.careers)) {
        this.careers.clear();
        data.careers.forEach((c: any) => {
          this.careers.push(this.fb.group({
            periodFrom: [c?.periodFrom || ''],
            periodTo: [c?.periodTo || ''],
            company: [c?.company || ''],
            position: [c?.position || ''],
            description: [c?.description || ''],
          }));
        });
      }
      if (Array.isArray(data.educations)) {
        this.educations.clear();
        data.educations.forEach((e: any) => {
          this.educations.push(this.fb.group({
            periodFrom: [e?.periodFrom || ''],
            periodTo: [e?.periodTo || ''],
            school: [e?.school || ''],
            major: [e?.major || ''],
          }));
        });
      }
      if (Array.isArray(data.skills)) {
        this.skills = [...data.skills];
      }
      if (typeof data.avatarPreview === 'string' && data.avatarPreview) {
        this.avatarPreview = data.avatarPreview;
      }
      if (typeof data.avatarScale === 'number' && data.avatarScale > 0) {
        this.avatarScale = data.avatarScale;
      }
      this.cdr.markForCheck();
    } catch (err) {
      console.warn('[ProfilePage] failed to load profile from storage:', err);
    }
  }

  private initForm(): void {
    this.profileForm = this.fb.group({
      // プロフィール情報
      lastName: ['', Validators.required],
      firstName: ['', Validators.required],
      furigana: [''],
      company: [''],
      department: [''],
      jobTitle: [''],
      catchphrase: [''],
      bio: [''],
      birthplace: [''],
      birthday: [''],

      // 連絡先
      phone: [''],
      address: [''],
      website: [''],

      // SNS
      facebook: [''],
      twitter: [''],
      instagram: [''],

      // 経歴 (FormArray)
      careers: this.fb.array([]),

      // 学歴 (FormArray)
      educations: this.fb.array([]),
    });
  }

  // === アバター ===
  onAvatarChange(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files[0]) {
      const file = input.files[0];
      if (file.size > 5 * 1024 * 1024) {
        this.notification.error('ファイルサイズは5MB以下にしてください');
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        this.avatarEditorSrc = reader.result as string;
        this.avatarZoom = 1;
        this.avatarPanX = 0;
        this.avatarPanY = 0;
        this.showAvatarEditor = true;
        this.cdr.markForCheck();
      };
      reader.readAsDataURL(file);
    }
  }

  onAvatarZoomIn(): void {
    this.avatarZoom = Math.min(this.avatarZoom + 0.1, 3);
  }

  onAvatarZoomOut(): void {
    this.avatarZoom = Math.max(this.avatarZoom - 0.1, 0.5);
  }

  onAvatarZoomChange(event: Event): void {
    this.avatarZoom = parseFloat((event.target as HTMLInputElement).value);
  }

  onAvatarDragStart(event: MouseEvent): void {
    event.preventDefault();
    this.isDragging = true;
    this.dragStartX = event.clientX;
    this.dragStartY = event.clientY;
    this.panStartX = this.avatarPanX;
    this.panStartY = this.avatarPanY;
  }

  onAvatarDragMove(event: MouseEvent): void {
    if (!this.isDragging) return;
    this.avatarPanX = this.panStartX + (event.clientX - this.dragStartX);
    this.avatarPanY = this.panStartY + (event.clientY - this.dragStartY);
  }

  onAvatarDragEnd(): void {
    this.isDragging = false;
  }

  onAvatarTouchStart(event: TouchEvent): void {
    if (event.touches.length === 1) {
      this.isDragging = true;
      this.dragStartX = event.touches[0].clientX;
      this.dragStartY = event.touches[0].clientY;
      this.panStartX = this.avatarPanX;
      this.panStartY = this.avatarPanY;
    }
  }

  onAvatarTouchMove(event: TouchEvent): void {
    if (!this.isDragging || event.touches.length !== 1) return;
    event.preventDefault();
    this.avatarPanX = this.panStartX + (event.touches[0].clientX - this.dragStartX);
    this.avatarPanY = this.panStartY + (event.touches[0].clientY - this.dragStartY);
    this.cdr.markForCheck();
  }

  onAvatarSave(): void {
    if (!this.avatarEditorSrc) return;
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const size = 256;
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext('2d')!;

      // 円形クリッピング
      ctx.beginPath();
      ctx.arc(size / 2, size / 2, size / 2, 0, Math.PI * 2);
      ctx.clip();

      // 画像をズーム・パンして描画
      const scale = this.avatarZoom;
      const imgW = img.width * scale;
      const imgH = img.height * scale;
      const drawX = (size - imgW) / 2 + this.avatarPanX * (size / 200);
      const drawY = (size - imgH) / 2 + this.avatarPanY * (size / 200);

      ctx.drawImage(img, drawX, drawY, imgW, imgH);

      this.avatarPreview = canvas.toDataURL('image/png');
      this.showAvatarEditor = false;
      this.cdr.markForCheck();
      this.notification.success('プロフィール画像を設定しました');
    };
    img.src = this.avatarEditorSrc;
  }

  onAvatarEditorCancel(): void {
    this.showAvatarEditor = false;
  }

  // === スキル ===
  addSkill(event: MatChipInputEvent): void {
    const value = (event.value || '').trim();
    if (value && !this.skills.includes(value)) {
      this.skills.push(value);
    }
    event.chipInput!.clear();
  }

  removeSkill(index: number): void {
    this.skills.splice(index, 1);
  }

  // === 経歴 ===
  get careers(): FormArray {
    return this.profileForm.get('careers') as FormArray;
  }

  addCareer(): void {
    this.careers.push(
      this.fb.group({
        periodFrom: [''],
        periodTo: [''],
        company: [''],
        position: [''],
        description: [''],
      })
    );
  }

  removeCareer(index: number): void {
    this.careers.removeAt(index);
  }

  // === 学歴 ===
  get educations(): FormArray {
    return this.profileForm.get('educations') as FormArray;
  }

  addEducation(): void {
    this.educations.push(
      this.fb.group({
        periodFrom: [''],
        periodTo: [''],
        school: [''],
        major: [''],
      })
    );
  }

  removeEducation(index: number): void {
    this.educations.removeAt(index);
  }

  // === 保存 ===
  onSave(): void {
    if (this.profileForm.invalid) {
      this.profileForm.markAllAsTouched();
      this.notification.error('必須項目を入力してください');
      return;
    }

    /* 修正 No.37 (2026-04-25): プロフィール情報を localStorage に永続化。
       アバター画像 (dataURL) とスキル・スケールも含めて保存することで、
       リロード/再遷移後も ngOnInit の loadProfileFromStorage() で復元できる。 */
    const formData = {
      ...this.profileForm.getRawValue(),
      skills: this.skills,
      avatarPreview: this.avatarPreview,
      avatarScale: this.avatarScale,
    };

    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(ProfilePageComponent.STORAGE_KEY, JSON.stringify(formData));
      }
    } catch (err) {
      console.warn('[ProfilePage] failed to persist profile:', err);
    }

    this.notification.success('プロフィールを保存しました');
  }

  /* 修正 No.36 (2026-04-25): プレビュー画像サイズのスライダー変更ハンドラ */
  onAvatarScaleChange(event: Event): void {
    const v = parseFloat((event.target as HTMLInputElement).value);
    if (!isNaN(v) && v > 0) {
      this.avatarScale = v;
      this.cdr.markForCheck();
    }
  }

  // === 退会 ===
  /* 修正 No.53 (2026-04-24): 独自 confirm モーダル化 */
  async onDeleteAccount(): Promise<void> {
    const ok = await this.confirmDialog.confirm({
      title: '退会の確認',
      message: '本当に退会しますか？この操作は取り消せません。',
      confirmText: '退会する',
      danger: true,
    });
    if (!ok) return;
    // TODO: 退会API呼び出し
    this.notification.warn('退会処理を受け付けました');
  }
}
